);

SELECT COUNT(*) FROM (
  SELECT 1 v FROM DUAL UNION ALL SELECT 2 v FROM DUAL
  MINUS
  SELECT 2 v FROM DUAL UNION ALL SELECT 3 v FROM DUAL
);
